"""Render audited new-case results with all prespecified failures visible."""
import csv,json
from run_qasper_interface_replication import ROOT,OUT,MODELS,ARMS,sha,save

def main():
    s=json.loads((OUT/'summary.json').read_text(encoding='utf-8'));audit=json.loads((OUT/'independent_audit.json').read_text(encoding='utf-8'));assert audit['audit_pass'];rows=[]
    lines=['# 新问题重复：原文、答案接口与状态额外收益（2026-10-03）','','## 一句话结论','','是否确认状态收益：'+('通过预设双模型门槛，仍限于本研究样本。' if s['advance_state'] else '未通过预设双模型门槛，不宣称自然论文状态接续成功。')+' 是否确认统一答案接口收益：'+('通过预设双模型门槛。' if s['confirm_interface'] else '未通过预设双模型门槛，不能作为普遍有效的改进。'),'','## 冻结设计','','本批12篇论文24问题，与上一批6论文12问题不重叠，沿用既有Qasper train结构指纹分区，至少2问题的论文列表第31–42项，每篇前2题。是本策略新读出，不是项目完全未接触的独立测试语料。冻结后完成所有调用才评分；未按答案、结果、来源长度或题型选择样本。两模型各24份实际生产状态、144次读出，合计336正式调用＋2预热。','','|方案|原文与状态|部署调用|','|---|---|---:|','|full|摘要＋全部正文段落|1|','|base|普通BM25前8完整段|1|','|wide|普通BM25前12完整段|1|','|base_bind|同base，加入题目决定的答案绑定|1|','|wide_bind|同wide，加入相同答案绑定|1|','|state_bind|同wide_bind，额外加入实际自产known/missing_queries/draft|2|','','答案绑定逐字复用上一轮规则：以助动词起首的问题输出Yes/No/unknown；其它只回答所问事实或完整列表，不复述、不加无关解释。state_bind与wide_bind使用相同原文和答案绑定，差别包含可见状态及其取用提示；它不是只改变状态位置的实验。状态是自述笔记，不是已核验事实，也不是原论文原生推理轨迹，因此不能据本批否定唐杰老师原方法。全部方案保留完整段落，没有动态检索或程序纠正状态。','','模型按4B后较小模型顺序分块，与上一轮反向；每模型读者顺序采用冻结随机排列轮转，24题中每方案在每位置恰好4次。temperature0、think=false、ctx32768、相同原生JSON schema，读者768/生产者384输出上限，不做质量重试或事后解析修补。正文不包含浮动图表或真实表格单元，full准确含义是可用摘要与full_text字段，非完整PDF。','','## 全部预设结果','','主评分：公开标注、多参考Counter token-F1；只有精确规范化unknown适配Unanswerable，错误计0。EM为规范化文本精确匹配补充项。论文簇20000次bootstrap，seed202610033；区间是点态探索性范围，不进行多重对比挑选。']
    for m in MODELS:
        v=s['models'][m];lines+=['',f'### {m}','','|方案|F1 %|文本EM %|平均答案词数|含生产者token|含生产者墙钟秒|失败|全证据覆盖/可映射题|布尔格式符合/题数|','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
        for a in ARMS:
            x=v['arms'][a];lines.append(f"|{a}|{100*x['f1']:.2f}|{100*x['em']:.2f}|{x['mean_words']:.2f}|{x['tokens']}|{x['wall_sec']:.3f}|{x['errors']}|{x['all_evidence_hits']}/{x['mapped_questions']}|{x['boolean_format_ok']}/{x['boolean_questions']}|");rows.append({'model':m,'arm':a,'f1':x['f1'],'tokens':x['tokens'],'wall_sec':x['wall_sec']})
        lines+=['','|预设配对差值|F1百分点|论文簇95%区间|','|---|---:|---|']
        for k,x in v['paired'].items():lines.append(f"|{k}|{100*x['difference']:+.2f}|[{100*x['paper_ci95'][0]:+.2f}, {100*x['paper_ci95'][1]:+.2f}]|")
        lines+=['',f"状态门槛：{v['state_gate']}；统一接口门槛：{v['interface_gate']}。压缩质量门槛（相对full下界>-3百分点、总token至少节约20%、无失败）："+json.dumps(v['compression_gates'],ensure_ascii=False)+'。']
    lines+=['','## 成本和可信度','','state_bind每个部署选择各自计入同一个实际生产者一次，没有把评估中的共享生产者当免费。准备阶段'+f"{s['prepare_sec']:.3f}"+'秒，预热单列。模型运行期间没有并行执行审计、绘图或分析；仍有固定模型分块、加载和缓存差异，墙钟只报告观察值，不宣称严格提速。不同模型架构/量化/状态质量同时变化，不能把模型间差异单独归因于参数量。','','程序审计独立重新生成选样、BM25排名、正文及偏移，重建所有请求、状态反馈、输出分数与轮转均衡；验证'+str(audit['formal_calls'])+'次正式HTTP请求、'+str(audit['state_bindings_verified'])+'个实际状态绑定。记录调用/解析失败'+str(audit['errors'])+'，输出达到预算'+str(audit['generation_cap_hits'])+'次。失败原始响应保留，不能把格式有效当事实有效。证据段落覆盖不是语义充分性，token-F1不能完整衡量事实正确性，尤其解释过长会降分。','','## 主线收敛','','本批结果单独报告，不把上一批自适应消融拼入确认样本。若双模型门槛失败，停止声称该状态方案为普遍改进，也不在这24题继续搜索最佳提示。第一目标仍是原方法小模型迁移及边界；下一步用原任务的可机械验证结构，检查由模型产生的真实状态、相同T/x/q顺序和原文长度交互。若真实论文低成本读出没有超过廉价基线，应保留为负结果和适用范围，而不是换指标制造成功。','','## 文件','','协议protocol_qasper_interface_replication_20261003.md；记录logs/qasper_interface_replication；R图paper/figures/qasper_interface_replication.pdf/png；范围审稿QASPER_INTERFACE_REPLICATION_REVIEW_20261003.md。主论文tex/PDF尚未全面重写，本阶段报告不等于整篇论文已完成审查。']
    path=ROOT/'paper/QASPER_INTERFACE_REPLICATION_20261003.md';path.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    with (ROOT/'paper/figures/data/qasper_interface_replication.csv').open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    save(OUT/'release_audit.json',{'formal_calls':336,'warmups':2,'audit_pass':True,'independent_new_strategy_cases':True,'source_project_holdout':False,'state_gate':s['advance_state'],'interface_gate':s['confirm_interface'],'report_sha256':sha(path.read_bytes()),'summary_sha256':sha((OUT/'summary.json').read_bytes()),'scope':'main manuscript remains incomplete'});print(path)

if __name__=='__main__':main()
